.quote {
  width: 420px;
  margin: 24px;
}

.quote-text {
  margin: 0;
}

/* ---- Solution ---- */
.quote {
  position: relative;
  padding: 40px 32px 28px;
  border-left: 6px solid #f97316;
  border-radius: 12px;
  background-color: #fff7ed;
}

.quote::before {
  content: "“";
  position: absolute;
  top: -8px;
  left: 20px;
  color: #fdba74;
  font-family: Georgia, serif;
  font-size: 96px;
  line-height: 1;
}

.quote-text {
  position: relative;
  color: #431407;
  font-family: Georgia, "Times New Roman", serif;
  font-size: 26px;
  font-style: italic;
  line-height: 1.3;
}

.author {
  margin-top: 16px;
  color: #c2410c;
  font-family: system-ui, sans-serif;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.author::before {
  content: "— ";
}
